import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String s = br.readLine();String t = br.readLine();if (s == null || t == null) {System.out.println("NO");return;}StringBuilder sb = new StringBuilder(s);String reversedS = sb.reverse().toString();if (reversedS.equals(t)) {System.out.println("YES");} else {System.out.println("NO");}}}